#!/usr/bin/env bash
# SPDX-License-Identifier: MIT
# Atlas KubeKit | By Atlas Richie
# BEGIN ATLAS KUBEKIT VERSION (generated by scripts/update-version.py)
ATLAS_KUBEKIT_VERSION='0.3.0'
if [ "${1:-}" = --version ] || [ "${1:-}" = -V ]; then
  printf 'Atlas KubeKit %s\n' "$ATLAS_KUBEKIT_VERSION"
  exit 0
fi
# END ATLAS KUBEKIT VERSION
set -euo pipefail
MIRROR="${1:-https://k8s.m.daocloud.io}"
LOCAL_REGISTRY_HOST="${2:-}"
CFG=/etc/containerd/config.toml
HOSTDIR=/etc/containerd/certs.d/registry.k8s.io
HOSTS="$HOSTDIR/hosts.toml"
[ "$(id -u)" -eq 0 ] || { echo 'Run as root' >&2; exit 1; }
command -v containerd >/dev/null && command -v python3 >/dev/null || { echo 'containerd or python3 is missing' >&2; exit 1; }
[ -f "$CFG" ] || { echo "Missing $CFG; run setup-k8s-node.sh first" >&2; exit 1; }
case "$MIRROR" in https://*) ;; *) echo 'Mirror URL must use https://' >&2; exit 1;; esac
if [ -n "$LOCAL_REGISTRY_HOST" ]; then
  python3 - "$LOCAL_REGISTRY_HOST" <<'PY'
import ipaddress, re, sys
value = sys.argv[1]
if not re.fullmatch(r"[A-Za-z0-9.-]+:[0-9]{1,5}", value):
    raise SystemExit("Local registry must be an IPv4 address or DNS hostname plus port")
host, raw_port = value.rsplit(":", 1)
port = int(raw_port)
if not 1 <= port <= 65535:
    raise SystemExit("Local registry port must be in 1..65535")
if ":" in host or host.startswith(".") or host.endswith(".") or ".." in host:
    raise SystemExit("Local registry host is invalid")
try:
    ipaddress.ip_address(host)
except ValueError:
    if len(host) > 253 or any(
        not re.fullmatch(r"[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?", label)
        for label in host.split(".")
    ):
        raise SystemExit("Local registry hostname is invalid")
PY
  python3 - "$LOCAL_REGISTRY_HOST" <<'PY'
import sys
import urllib.error
import urllib.request

url = f"http://{sys.argv[1]}/v2/"
try:
    with urllib.request.urlopen(url, timeout=5) as response:
        status = response.status
except urllib.error.HTTPError as response:
    status = response.code
except (OSError, TimeoutError) as exc:
    raise SystemExit(f"Local HTTP registry is unreachable from this node: {exc}") from None
if status not in {200, 401}:
    raise SystemExit(f"Local HTTP registry returned unexpected status {status}")
print(f"Local registry reachable: {url} (HTTP {status})")
PY
fi

TMP_HOSTS=$(mktemp)
TMP_CFG=$(mktemp)
TMP_LOCAL_HOSTS=$(mktemp)
trap 'rm -f "$TMP_HOSTS" "$TMP_CFG" "$TMP_LOCAL_HOSTS"' EXIT
cat > "$TMP_HOSTS" <<EOF
server = "https://registry.k8s.io"

[host."$MIRROR"]
  capabilities = ["pull", "resolve"]
EOF
if [ -n "$LOCAL_REGISTRY_HOST" ]; then
  LOCAL_HOSTDIR="/etc/containerd/certs.d/$LOCAL_REGISTRY_HOST"
  LOCAL_HOSTS="$LOCAL_HOSTDIR/hosts.toml"
  cat > "$TMP_LOCAL_HOSTS" <<EOF
# Managed by Atlas KubeKit: local HTTP image registry.
server = "http://$LOCAL_REGISTRY_HOST"

[host."http://$LOCAL_REGISTRY_HOST"]
  capabilities = ["pull", "resolve"]
EOF
  if [ -e "$LOCAL_HOSTS" ] && ! cmp -s "$TMP_LOCAL_HOSTS" "$LOCAL_HOSTS" \
      && ! grep -Fq 'Managed by Atlas KubeKit: local HTTP image registry.' "$LOCAL_HOSTS"; then
    echo "Existing unowned containerd registry config conflicts: $LOCAL_HOSTS" >&2
    exit 1
  fi
fi

python3 - "$CFG" "$TMP_CFG" <<'PY'
import pathlib, re, sys
src, dst = map(pathlib.Path, sys.argv[1:])
lines = src.read_text().splitlines(keepends=True)
targets = {
    "[plugins.'io.containerd.cri.v1.images'.registry]",
    '[plugins."io.containerd.cri.v1.images".registry]',
    '[plugins."io.containerd.grpc.v1.cri".registry]',
}
start = next((i for i, line in enumerate(lines) if line.strip() in targets), None)
if start is None:
    raise SystemExit('Unrecognized containerd CRI registry section; original configuration preserved')
end = next((i for i in range(start + 1, len(lines)) if lines[i].lstrip().startswith('[')), len(lines))
indices = [i for i in range(start + 1, end) if re.match(r'\s*config_path\s*=', lines[i])]
if len(indices) > 1:
    raise SystemExit('Duplicate config_path in registry section; original configuration preserved')
wanted = "      config_path = '/etc/containerd/certs.d'\n"
if indices:
    lines[indices[0]] = wanted
else:
    lines.insert(start + 1, wanted)
dst.write_text(''.join(lines))
PY

changed=0
restart_required=0
if ! cmp -s "$TMP_CFG" "$CFG"; then
  cp -a "$CFG" "$CFG.bak.$(date +%Y%m%d%H%M%S)"
  cat "$TMP_CFG" > "$CFG"
  changed=1
  restart_required=1
fi
mkdir -p "$HOSTDIR"
if ! cmp -s "$TMP_HOSTS" "$HOSTS" 2>/dev/null; then
  install -m 644 "$TMP_HOSTS" "$HOSTS"
  changed=1
fi
if [ -n "$LOCAL_REGISTRY_HOST" ]; then
  if ! cmp -s "$TMP_LOCAL_HOSTS" "$LOCAL_HOSTS" 2>/dev/null; then
    install -d -m 755 "$LOCAL_HOSTDIR"
    install -m 644 "$TMP_LOCAL_HOSTS" "$LOCAL_HOSTS"
    changed=1
  fi
fi
if [ "$restart_required" -eq 1 ]; then
  systemctl restart containerd
fi
systemctl is-active --quiet containerd || { echo 'containerd is not active' >&2; exit 1; }
containerd config dump | grep -Fq '/etc/containerd/certs.d' || { echo 'containerd effective configuration does not enable certs.d' >&2; exit 1; }
if [ "$changed" -eq 1 ]; then
  echo "containerd registry configuration updated: mirror=$MIRROR local=${LOCAL_REGISTRY_HOST:-disabled} restart=$restart_required"
else
  echo "containerd registry configuration already current; restart skipped: mirror=$MIRROR local=${LOCAL_REGISTRY_HOST:-disabled}"
fi
